```python
"""
Python Decorators: A Comprehensive Tutorial
===========================================

A decorator is a design pattern in Python that allows you to modify the functionality
of a function or class without permanently modifying its structure.
"""

# ============================================================================
# 1. BASIC DECORATOR SYNTAX
# ============================================================================

print("=" * 70)
print("1. BASIC DECORATOR SYNTAX")
print("=" * 70)

# A decorator is a function that takes another function and extends its behavior
def simple_decorator(func):
    """Basic decorator that wraps a function"""
    def wrapper():
        print("Something is happening before the function is called.")
        func()
        print("Something is happening after the function is called.")
    return wrapper

# Using the decorator with @ syntax
@simple_decorator
def say_hello():
    print("Hello!")

say_hello()
print()

# The @ syntax is equivalent to:
# say_hello = simple_decorator(say_hello)


# Decorator that works with function arguments
def decorator_with_args(func):
    """Decorator that handles function arguments using *args and **kwargs"""
    def wrapper(*args, **kwargs):
        print(f"Calling {func.__name__} with args={args}, kwargs={kwargs}")
        result = func(*args, **kwargs)
        print(f"{func.__name__} returned: {result}")
        return result
    return wrapper

@decorator_with_args
def add(a, b):
    return a + b

@decorator_with_args
def greet(name, greeting="Hello"):
    return f"{greeting}, {name}!"

print("\nExamples with arguments:")
add(5, 3)
print()
greet("Alice")
print()
greet("Bob", greeting="Hi")
print()


# Preserving function metadata with functools.wraps
from functools import wraps

def better_decorator(func):
    """Decorator that preserves the original function's metadata"""
    @wraps(func)
    def wrapper(*args, **kwargs):
        """Wrapper function"""
        return func(*args, **kwargs)
    return wrapper

@better_decorator
def documented_function():
    """This function has documentation"""
    pass

print("Without @wraps, function metadata is lost.")
print(f"Function name: {documented_function.__name__}")
print(f"Function doc: {documented_function.__doc__}")
print()


# ============================================================================
# 2. DECORATORS WITH ARGUMENTS
# ============================================================================

print("=" * 70)
print("2. DECORATORS WITH ARGUMENTS")
print("=" * 70)

# To pass arguments to decorators, we need an extra level of nesting
def repeat(times):
    """Decorator factory that repeats function execution"""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            results = []
            for _ in range(times):
                result = func(*args, **kwargs)
                results.append(result)
            return results
        return wrapper
    return decorator

@repeat(times=3)
def say_hi(name):
    message = f"Hi, {name}!"
    print(message)
    return message

print("\nRepeating function 3 times:")
results = say_hi("Charlie")
print(f"Results: {results}")
print()


# Decorator with optional arguments
def debug(func=None, *, prefix="DEBUG"):
    """Decorator that can be used with or without arguments"""
    def decorator(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            print(f"{prefix}: Calling {fn.__name__}")
            result = fn(*args, **kwargs)
            print(f"{prefix}: {fn.__name__} returned {result}")
            return result
        return wrapper

    # Handle both @debug and @debug(prefix="...")
    if func is None:
        return decorator
    else:
        return decorator(func)

@debug
def multiply(x, y):
    return x * y

@debug(prefix="TRACE")
def divide(x, y):
    return x / y

print("Using @debug without arguments:")
multiply(4, 5)
print()

print("Using @debug with arguments:")
divide(10, 2)
print()


# Parameterized decorator for access control
def require_permission(permission):
    """Decorator that checks if user has required permission"""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Simulate permission check
            user_permissions = {"read", "write"}  # Mock user permissions

            if permission in user_permissions:
                return func(*args, **kwargs)
            else:
                raise PermissionError(f"Permission '{permission}' required")
        return wrapper
    return decorator

@require_permission("read")
def read_data():
    return "Reading data..."

@require_permission("admin")
def delete_data():
    return "Deleting data..."

print("Testing permission decorator:")
print(read_data())

try:
    delete_data()
except PermissionError as e:
    print(f"Error: {e}")
print()


# ============================================================================
# 3. CLASS DECORATORS
# ============================================================================

print("=" * 70)
print("3. CLASS DECORATORS")
print("=" * 70)

# Decorator applied to a class
def add_repr(cls):
    """Class decorator that adds a __repr__ method"""
    def __repr__(self):
        attrs = ', '.join(f"{k}={v!r}" for k, v in self.__dict__.items())
        return f"{cls.__name__}({attrs})"

    cls.__repr__ = __repr__
    return cls

@add_repr
class Person:
    def __init__(self, name, age):
        self.name = name
        self.age = age

person = Person("Alice", 30)
print(f"Person representation: {person}")
print()


# Class decorator with arguments
def singleton(cls):
    """Decorator that makes a class a singleton"""
    instances = {}

    @wraps(cls)
    def get_instance(*args, **kwargs):
        if cls not in instances:
            instances[cls] = cls(*args, **kwargs)
        return instances[cls]

    return get_instance

@singleton
class Database:
    def __init__(self, connection_string):
        self.connection_string = connection_string
        print(f"Connecting to database: {connection_string}")

db1 = Database("postgresql://localhost/mydb")
db2 = Database("mysql://localhost/other")  # Same instance
print(f"db1 is db2: {db1 is db2}")
print()


# Using a class as a decorator
class CountCalls:
    """Decorator class that counts function calls"""
    def __init__(self, func):
        self.func = func
        self.count = 0
        wraps(func)(self)  # Preserve function metadata

    def __call__(self, *args, **kwargs):
        self.count += 1
        print(f"Call {self.count} to {self.func.__name__}")
        return self.func(*args, **kwargs)

@CountCalls
def process_data(data):
    return f"Processing: {data}"

process_data("item1")
process_data("item2")
process_data("item3")
print(f"Total calls: {process_data.count}")
print()


# Class decorator with arguments
class Retry:
    """Decorator class that retries a function on failure"""
    def __init__(self, max_attempts=3, delay=1):
        self.max_attempts = max_attempts
        self.delay = delay

    def __call__(self, func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            import time

            for attempt in range(1, self.max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    print(f"Attempt {attempt} failed: {e}")
                    if attempt == self.max_attempts:
                        raise
                    time.sleep(self.delay)
        return wrapper

@Retry(max_attempts=3, delay=0.1)
def unreliable_function():
    import random
    if random.random() < 0.7:
        raise ValueError("Random failure")
    return "Success!"

print("Testing retry decorator:")
try:
    result = unreliable_function()
    print(f"Result: {result}")
except ValueError as e:
    print(f"All attempts failed: {e}")
print()


# ============================================================================
# 4. BUILT-IN DECORATORS
# ============================================================================

print("=" * 70)
print("4. BUILT-IN DECORATORS")
print("=" * 70)

# @property: Create managed attributes
class Temperature:
    """Class demonstrating @property decorator"""
    def __init__(self, celsius):
        self._celsius = celsius

    @property
    def celsius(self):
        """Get temperature in Celsius"""
        return self._celsius

    @celsius.setter
    def celsius(self, value):
        """Set temperature in Celsius"""
        if value < -273.15:
            raise ValueError("Temperature below absolute zero")
        self._celsius = value

    @property
    def fahrenheit(self):
        """Get temperature in Fahrenheit"""
        return (self._celsius * 9/5) + 32

    @fahrenheit.setter
    def fahrenheit(self, value):
        """Set temperature using Fahrenheit"""
        self.celsius = (value - 32) * 5/9

temp = Temperature(25)
print(f"Temperature: {temp.celsius}°C = {temp.fahrenheit}°F")
temp.fahrenheit = 100
print(f"Updated: {temp.celsius}°C = {temp.fahrenheit}°F")
print()


# @staticmethod and @classmethod
class MathOperations:
    """Class demonstrating @staticmethod and @classmethod"""
    base_multiplier = 10

    @staticmethod
    def add(a, b):
        """Static method - doesn't access class or instance"""
        return a + b

    @classmethod
    def multiply_by_base(cls, value):
        """Class method - accesses class attributes"""
        return value * cls.base_multiplier

    @classmethod
    def create_with_multiplier(cls, multiplier):
        """Factory method using classmethod"""
        instance = cls()
        instance.base_multiplier = multiplier
        return instance

print(f"Static method: {MathOperations.add(5, 3)}")
print(f"Class method: {MathOperations.multiply_by_base(5)}")
print()


# @abstractmethod for abstract base classes
from abc import ABC, abstractmethod

class Shape(ABC):
    """Abstract base class for shapes"""

    @abstractmethod
    def area(self):
        """Calculate area - must be implemented by subclasses"""
        pass

    @abstractmethod
    def perimeter(self):
        """Calculate perimeter - must be implemented by subclasses"""
        pass

class Rectangle(Shape):
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height

    def perimeter(self):
        return 2 * (self.width + self.height)

rect = Rectangle(5, 3)
print(f"Rectangle area: {rect.area()}")
print(f"Rectangle perimeter: {rect.perimeter()}")
print()


# @dataclass (Python 3.7+)
from dataclasses import dataclass, field
from typing import List

@dataclass
class Book:
    """Dataclass example"""
    title: str
    author: str
    year: int
    tags: List[str] = field(default_factory=list)

    def __post_init__(self):
        """Called after __init__"""
        if self.year < 1450:
            raise ValueError("Books before printing press are not supported")

book = Book("1984", "George Orwell", 1949, ["dystopia", "fiction"])
print(f"Book: {book}")
print()


# @lru_cache for memoization
from functools import lru_cache

@lru_cache(maxsize=128)
def fibonacci(n):
    """Cached fibonacci calculation"""
    if n < 2:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

print("Fibonacci with caching:")
print(f"fib(10) = {fibonacci(10)}")
print(f"fib(20) = {fibonacci(20)}")
print(f"Cache info: {fibonacci.cache_info()}")
print()


# ============================================================================
# 5. PRACTICAL EXAMPLES
# ============================================================================

print("=" * 70)
print("5. PRACTICAL EXAMPLES")
print("=" * 70)

# Example 1: Timing decorator
import time

def timer(func):
    """Measure function execution time"""
    @wraps(func)
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        end = time.time()
        print(f"{func.__name__} took {end - start:.4f} seconds")
        return result
    return wrapper

@timer
def slow_function():
    """Simulate slow operation"""
    time.sleep(0.1)
    return "Done"

print("Timing example:")
slow_function()
print()


# Example 2: Logging decorator
import logging

logging.basicConfig(level=logging.INFO)

def log_calls(func):
    """Log function calls with arguments and results"""
    @wraps(func)
    def wrapper(*args, **kwargs):
        logger = logging.getLogger(func.__module__)
        logger.info(f"Calling {func.__name__} with args={args}, kwargs={kwargs}")
        try:
            result = func(*args, **kwargs)
            logger.info(f"{func.__name__} returned {result}")
            return result
        except Exception as e:
            logger.error(f"{func.__name__} raised {type(e).__name__}: {e}")
            raise
    return wrapper

@log_calls
def divide_numbers(a, b):
    return a / b

print("Logging example:")
divide_numbers(10, 2)
try:
    divide_numbers(10, 0)
except ZeroDivisionError:
    pass
print()


# Example 3: Validation decorator
def validate_types(**type_hints):
    """Validate function argument types"""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Get function signature
            import inspect
            sig = inspect.signature(func)
            bound_args = sig.bind(*args, **kwargs)
            bound_args.apply_defaults()

            # Validate types
            for param_name, expected_type in type_hints.items():
                if param_name in bound_args.arguments:
                    value = bound_args.arguments[param_name]
                    if not isinstance(value, expected_type):
                        raise TypeError(
                            f"{param_name} must be {expected_type.__name__}, "
                            f"got {type(value).__name__}"
                        )

            return func(*args, **kwargs)
        return wrapper
    return decorator

@validate_types(name=str, age=int)
def create_user(name, age):
    return {"name": name, "age": age}

print("Validation example:")
print(create_user("Alice", 30))
try:
    create_user("Bob", "thirty")
except TypeError as e:
    print(f"Validation error: {e}")
print()


# Example 4: Rate limiting decorator
from collections import deque
from datetime import datetime, timedelta

def rate_limit(max_calls, time_window):
    """Limit function calls to max_calls per time_window seconds"""
    def decorator(func):
        calls = deque()

        @wraps(func)
        def wrapper(*args, **kwargs):
            now = datetime.now()

            # Remove old calls outside the time window
            while calls and calls[0] < now - timedelta(seconds=time_window):
                calls.popleft()

            # Check if we can make a new call
            if len(calls) >= max_calls:
                raise RuntimeError(
                    f"Rate limit exceeded: {max_calls} calls per {time_window}s"
                )

            calls.append(now)
            return func(*args, **kwargs)

        return wrapper
    return decorator

@rate_limit(max_calls=3, time_window=5)
def api_call(endpoint):
    return f"Calling {endpoint}"

print("Rate limiting example:")
for i in range(4):
    try:
        print(api_call(f"/endpoint{i}"))
    except RuntimeError as e:
        print(f"Error: {e}")
print()


# Example 5: Caching with TTL (Time To Live)
from datetime import datetime

def cache_with_ttl(ttl_seconds):
    """Cache function results with expiration time"""
    def decorator(func):
        cache = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            # Create cache key from arguments
            key = (args, tuple(sorted(kwargs.items())))

            # Check cache
            if key in cache:
                result, timestamp = cache[key]
                age = (datetime.now() - timestamp).total_seconds()
                if age < ttl_seconds:
                    print(f"Cache hit (age: {age:.1f}s)")
                    return result
                else:
                    print("Cache expired")

            # Call function and cache result
            print("Cache miss - calling function")
            result = func(*args, **kwargs)
            cache[key] = (result, datetime.now())
            return result

        wrapper.clear_cache = lambda: cache.clear()
        return wrapper
    return decorator

@cache_with_ttl(ttl_seconds=2)
def fetch_data(user_id):
    """Simulate expensive data fetch"""
    time.sleep(0.1)
    return f"Data for user {user_id}"

print("TTL caching example:")
print(fetch_data(1))
print(fetch_data(1))  # Cache hit
time.sleep(2.1)
print(fetch_data(1))  # Cache expired
print()


# Example 6: Decorator chaining
@timer
@log_calls
@cache_with_ttl(ttl_seconds=10)
def complex_calculation(x, y):
    """Example of stacking multiple decorators"""
    time.sleep(0.1)
    return x ** y

print("Decorator chaining example:")
print(f"Result: {complex_calculation(2, 10)}")
print(f"Result: {complex_calculation(2, 10)}")  # Cached
print()


# Example 7: Context-aware decorator
import threading

_request_context = threading.local()

def with_context(**context_vars):
    """Decorator that sets request context"""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Save old context
            old_context = {
                k: getattr(_request_context, k, None)
                for k in context_vars.keys()
            }

            # Set new context
            for key, value in context_vars.items():
                setattr(_request_context, key, value)

            try:
                return func(*args, **kwargs)
            finally:
                # Restore old context
                for key, value in old_context.items():
                    if value is None:
                        delattr(_request_context, key)
                    else:
                        setattr(_request_context, key, value)

        return wrapper
    return decorator

def get_current_user():
    """Get current user from context"""
    return getattr(_request_context, 'user_id', None)

@with_context(user_id=123, request_id="abc-456")
def process_request():
    user = get_current_user()
    return f"Processing request for user {user}"

print("Context-aware decorator example:")
print(process_request())
print(f"User outside context: {get_current_user()}")
print()


print("=" * 70)
print("SUMMARY")
print("=" * 70)
print("""
Key Takeaways:
1. Basic decorators wrap functions to modify behavior
2. Use @wraps to preserve function metadata
3. Decorator factories allow passing arguments to decorators
4. Classes can be decorators or be decorated
5. Built-in decorators: @property, @staticmethod, @classmethod, @lru_cache, @dataclass
6. Practical uses: timing, logging, validation, caching, rate limiting, access control

Decorator execution order (bottom to top):
    @decorator1
    @decorator2
    @decorator3
    def func():
        pass

    Is equivalent to: func = decorator1(decorator2(decorator3(func)))
""")
